import subprocess

def hashpump_cli(orig_hash, orig_data, append, keylen):
    cmd = ["hashpump", "-s", orig_hash, "-d", orig_data, "-a", append, "-k", str(keylen)]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
