import base64
import sys

def has_null_or_nonascii(data: bytes):
    # Check for null bytes and for bytes outside printable ASCII or ampersand (padding, etc)
    return any(x == 0 or (x < 0x20 and x not in (0x0a, 0x0d)) or x > 0x7e for x in data)

def clean_base64_payload(orig_b64: str, appended: str):
    orig_bytes = base64.b64decode(orig_b64)
    testb = orig_bytes + appended.encode()
    b64_payload = base64.b64encode(testb)
    # Check for nulls/unprintable chars in appended area of payload
    return b64_payload.decode(), has_null_or_nonascii(testb)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <orig_b64> <inject_string>")
        sys.exit(-1)
    orig, inj = sys.argv[1], sys.argv[2]
    output, unprint = clean_base64_payload(orig, inj)
    print(output)
    print('Has_bad_bytes:', unprint)

