import base64
import requests
import hashpumpy

id_b64 = 'YWRtaW49RmFsc2UmYWNjZXNzX3NlbnNpdGl2ZT1GYWxzZSZhdXRob3I9dGVzdCZub3RlPWFiYyZlbnRyeW51bT03ODMmYWRtaW49VHJ1ZSZhY2Nlc3Nfc2Vuc2l0aXZlPVRydWUmZW50cnludW09Nw=='
id_raw = base64.b64decode(id_b64)

# Since the POST requires the integrity, we must get a valid hash - guessing a default hash won't work, SHA1(SECRET + message)
# Let's enumerate possible secret lengths, using hashpumpy, and test until a flag is returned.
for key_length in range(8, 21):
    for fake_prev_hash in ['0'*40]:
        try:
            new_hash, _ = hashpumpy.hashpump(fake_prev_hash, '', id_raw.decode('latin1'), key_length)
        except Exception:
            continue
        payload = {'id': id_b64, 'integrity': new_hash}
        try:
            resp = requests.post('http://crypto.chal.csaw.io:5000/view', data=payload, timeout=6)
            if 'flag{' in resp.text:
                print(resp.text)
                exit(0)
            if 'invalid' in resp.text:
                continue
        except Exception:
            continue
print('No flag found. Likely need proper hash (get from /new endpoint).')

